      PROGRAM MKDTX
      CHARACTER*80 R
      INTEGER N
      OPEN(1,FILE='DTEXTV.DAT',STATUS='OLD',FORM='FORMATTED',READONLY)
      OPEN(2,FILE='DTEXT.DAT',STATUS='NEW',FORM='UNFORMATTED',
     1 ACCESS='DIRECT',RECL=20)
      N = 0
   10 READ(1,'(A)',END=20) R
      N = N + 1
      WRITE(2,REC=N) R
      GO TO 10
   20 CLOSE(1)
      CLOSE(2)
      END
